/* ══════════════════════════════════════════════════════
   المواقع: الساحة + المخازن — v17.34
   ──────────────────────────────────────────────────────
   ① الساحة ليست مخزناً. هي موقع مستقل، ويُعرض اسمها
     «الساحة» فقط — بلا كلمة «مخزن» أمامها في أي مكان.
   ② المخازن ثلاثة: ابو ابراهيم · ابراهيم · بركات،
     وتُعرض بصيغة «مخزن فلان».
   ③ سبب اختلاف المفتاح عن الاسم:
     القيمة المخزَّنة في فايربيس منذ البداية للساحة هي
     "ابو ابراهيم"، وكل السجلات القديمة تحمل هذه القيمة
     وتعني «الساحة». لذلك أُعطي المخزن الجديد «ابو ابراهيم»
     مفتاحاً مختلفاً هو "مخزن ابو ابراهيم" حتى لا تختلط
     سجلات الساحة القديمة بسجلات المخزن الجديد.
     ⚠️ لا تُغيّر المفاتيح أبداً — غيّر التسمية فقط.
══════════════════════════════════════════════════════ */
const YARD="ابو ابراهيم";                                 // مفتاح الساحة (تاريخي)
const WH_ONLY=["مخزن ابو ابراهيم","ابراهيم","بركات"];      // المخازن فقط (بلا الساحة)
const WHS=[YARD,...WH_ONLY];                              // كل المواقع: الساحة + المخازن
const WH_LABELS={
  "ابو ابراهيم":"الساحة",          // السجلات القديمة = الساحة
  "مخزن ابو ابراهيم":"ابو ابراهيم", // المخزن الجديد
};
const isYard=wh=>wh===YARD;
function whName(wh){
  if(!wh)return wh||"";
  return WH_LABELS[wh]||wh;
}
/* الاسم الكامل للعرض: «الساحة» وحدها، و«مخزن فلان» للمخازن */
function whTitle(wh){
  if(!wh)return "";
  return isYard(wh)?"الساحة":("مخزن "+whName(wh));
}
/* أيقونة الموقع: الساحة ليست مصنعاً */
const whIcon=wh=>isYard(wh)?"🏟️":"🏭";
/* أيقونة + اسم كامل — الصيغة المعتمدة في العناوين */
const whFull=wh=>whIcon(wh)+" "+whTitle(wh);
/* كلمة الحقل: «الموقع» للساحة و«المخزن» للمخازن */
const whFieldLbl=wh=>isYard(wh)?"الموقع":"المخزن";
const PROVS=["بغداد","البصرة","الموصل","أربيل","كركوك","النجف","كربلاء","الحلة","الديوانية","السماوة","العمارة","الناصرية","الكوت","الرمادي","تكريت","بعقوبة","الفلوجة","سامراء","دهوك","السليمانية","خانقين","أخرى"];

